def main():
 p=argparse.ArgumentParser();p.add_argument('--candidate',type=Path,required=True);p.add_argument('--report',type=Path,required=True);a=p.parse_args()
 outputs={};stats={}
 for name,rules in RULES.items():
  f=a.candidate/name
  original=f.read_text(encoding='utf-8-sig');s=original
  for old,new,count in rules:
   if s.count(old)!=count or new in s:raise ValueError('Unexpected source anchor: '+name+': '+old)
   s=s.replace(old,new)
  reverse=s
  for old,new,count in reversed(rules):
   if reverse.count(new)!=count:raise ValueError('Reverse anchor: '+name)
   reverse=reverse.replace(new,old)
  if reverse!=original:raise ValueError('Non-reversible patch: '+name)
  raw=b'\xef\xbb\xbf'+s.encode('utf-8')
  outputs[f]=raw;stats[name]={'anchors':len(rules),'occurrences':sum(r[2] for r in rules),'sha256':hashlib.sha256(raw).hexdigest()}
 for f,raw in outputs.items():f.write_bytes(raw)
 a.report.write_text(json.dumps({'schema':'adPEAS-RU.MIG19d.Source.1','files':stats,'helpCommandDescriptions':50,'helpCategories':9,'moduleLabels':11,'objectTitleLabels':94,'realADTestPerformed':False,'canonicalDefinitionsModified':False},indent=2)+'\n',encoding='utf-8')
 print('PASS MIG19d reversible display localization')
if __name__=='__main__':main()
